---------------------------------------------------------------------------------------------------
-- Runtime helpers (written by tools/build_art.py): sheet paths per format and tier, lazy person
-- sprite decoding, and compatibility tables for 0.1.0 callers (floors/walls/persons lists).
---------------------------------------------------------------------------------------------------
A.format = "tga"
A.sheets, A.sheetsLo = {}, {}
-- the shell's title images (separate files): A.ui = { titleBackdrop = path, logo = path }
A.ui = {}
function A.SetFormat(fmt)
    if fmt ~= "tga" and fmt ~= "blp" then return false, "unknown art format '" .. tostring(fmt) .. "' (tga or blp)" end
    A.format = fmt
    for n, base in ipairs(A.files) do
        -- a --lo-only package has no hi sheets: every caller gets the lo file (same layout, and
        -- texture coordinates are fractions of the sheet, so they stay valid)
        A.sheets[n] = A.dir .. base .. (A.loOnly and "_lo." or ".") .. fmt
        A.sheetsLo[n] = A.dir .. base .. "_lo." .. fmt
    end
    for key, base in pairs(A.uiFiles or {}) do A.ui[key] = A.dir .. base .. "." .. fmt end
    if SS.Render and SS.Render.OnArtFormat then SS.Render.OnArtFormat(fmt) end
    return true
end
A.SetFormat("tga")

-- Person sprites: SS.Art.sprites["p:<age>:<pose>:<frame>:<k>:<layer>"] decodes the frame's packed
-- string the first time any of its layers is asked for.
local function decodeFrame(fkey)
    local s = P[fkey]
    if not s then return false end
    P[fkey] = nil
    for rec in s:gmatch("[^;]+") do
        local f, n = {}, 0
        for v in rec:gmatch("[^,]+") do n = n + 1; f[n] = v end
        local r = { tonumber(f[2]), tonumber(f[3]), tonumber(f[4]), tonumber(f[5]), tonumber(f[6]), tonumber(f[7]), tonumber(f[8]),
            tonumber(f[9]) or 0, tonumber(f[10]) or 0, f[11] or "" }
        rawset(S, "p:" .. fkey .. ":" .. f[1], r)
    end
    return true
end
A.DecodePersonFrame = decodeFrame
setmetatable(S, { __index = function(t, name)
    if type(name) ~= "string" then return nil end
    -- the household creator's option names (hood art request 6) resolve to the layer drawing them
    local al = A.creatorArt and A.creatorArt[name]
    if al then
        local r = t[al]
        if r then rawset(t, name, r) end
        return r
    end
    if name:sub(1, 2) ~= "p:" then return nil end
    local fkey = name:match("^p:([^:]+:[^:]+:%d+:%d+):")
    if fkey and P[fkey] and decodeFrame(fkey) then return rawget(t, name) end
    return nil
end })
function A.PersonLayers(fkey) return A.personLayers and A.personLayers[fkey] end

-- 0.1.0 compatibility: floors[name] = list of sprites (finish ids resolve through their pattern),
-- walls["<kind>:<full|short>:<x|y>"] = { wall, fix }, persons["<hair>:idle:<k>"] = { skin, ... }.
local FP = A.floorPatterns or {}
local function floorList(pat)
    if not FP[pat] then return nil end
    return { "floor:" .. pat .. ":0:00", "floor:" .. pat .. ":0:01", "floor:" .. pat .. ":0:10", "floor:" .. pat .. ":0:11" }
end
local OLD_FLOOR = { wood = "planks", tile = "tiles", carpet = "carpet", path = "stone", grass = "grass" }
A.floors = setmetatable({}, { __index = function(t, id)
    local pat = OLD_FLOOR[id] or (FP[id] and id)
    if not pat and SS.Finishes and SS.Finishes.floors and type(SS.Finishes.floors[id]) == "table" then
        local look = SS.Finishes.floors[id].look
        pat = look and FP[look.pattern] and look.pattern
    end
    local l = pat and floorList(pat)
    if l then rawset(t, id, l) end
    return l
end })
local function wallSprite(pat, vaxis, h) return "wall:" .. pat .. ":" .. (vaxis == "x" and "u" or "v") .. ":" .. h end
A.walls = setmetatable({}, { __index = function(t, key)
    local kind, h, vaxis = tostring(key):match("^(%a+):(%a+):(%a)$")
    if not kind then return nil end
    local e = { wall = wallSprite("paint", vaxis, h) }
    local ax = vaxis == "x" and "u" or "v"
    if kind == "door" then e.fix = "door:door_basic:" .. ax .. ":" .. h
    elseif kind == "window" and h == "full" then e.fix = "window:window_basic:" .. ax .. ":full"
    elseif kind == "arch" then e.fix = "door:arch_round:" .. ax .. ":" .. h end
    rawset(t, key, e)
    return e
end })
A.persons = setmetatable({}, { __index = function(t, key)
    local hair, pose, k = tostring(key):match("^([%w_]+):(%w+):(%d)$")
    if not hair then return nil end
    local f = "p:a:" .. pose .. ":0:" .. k .. ":"
    if not S[f .. "skin"] then return nil end
    local e = { skin = f .. "skin", head = f .. "head1", eyes = f .. "eyes1", bottom = f .. "bo:trousers", shoes = f .. "sh:shoes",
        top = f .. "to:tee", hair = S[f .. "ha:" .. hair] and (f .. "ha:" .. hair) or (f .. "ha:short") }
    rawset(t, key, e)
    return e
end })

